WITH wp_counts AS ( SELECT wp_customer_sk, COUNT(*) AS wp_cnt FROM web_page GROUP BY wp_customer_sk ), sales_data AS ( SELECT cs.cs_ship_mode_sk AS ship_mode, cs.cs_sold_time_sk, cs.cs_net_paid_inc_tax, cs.cs_ext_ship_cost, cs.cs_net_profit, cs.cs_ship_customer_sk AS cust_sk, c.c_preferred_cust_flag, t.t_hour, t.t_shift, CASE WHEN cs.cs_ext_ship_cost < 10 THEN 'Low' WHEN cs.cs_ext_ship_cost < 30 THEN 'Medium' ELSE 'High' END AS ship_cost_bucket, COALESCE(wp_counts.wp_cnt, 0) AS wp_cnt FROM catalog_sales cs JOIN time_dim t ON cs.cs_sold_time_sk = t.t_time_sk JOIN customer c ON cs.cs_ship_customer_sk = c.c_customer_sk LEFT JOIN wp_counts ON c.c_customer_sk = wp_counts.wp_customer_sk ), aggregated AS ( SELECT ship_mode, ship_cost_bucket, t_hour, t_shift, MIN(cs_sold_time_sk) AS first_sold_time, COUNT(*) AS sales_cnt, SUM(cs_net_paid_inc_tax) AS total_net_paid_inc_tax, SUM(cs_net_profit) AS total_net_profit, AVG(wp_cnt) AS avg_wp_cnt FROM sales_data GROUP BY ship_mode, ship_cost_bucket, t_hour, t_shift ) SELECT a.ship_mode, a.ship_cost_bucket, a.t_hour, a.t_shift, a.sales_cnt, a.total_net_paid_inc_tax, a.total_net_profit, a.avg_wp_cnt, ROW_NUMBER() OVER (PARTITION BY a.ship_mode ORDER BY a.first_sold_time) AS seq_in_mode, SUM(a.total_net_paid_inc_tax) OVER (PARTITION BY a.ship_mode ORDER BY a.first_sold_time ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_paid FROM aggregated a ORDER BY a.ship_mode, seq_in_mode LIMIT 100
